/// GPU uploads shared by preview worlds that use the same wgpu device.
#[derive(Clone, Default)]
pub struct SharedGpuMeshCache {
    entries: Arc<Mutex<HashMap<(usize, MeshContentKey), GpuMesh>>>,
}

impl SharedGpuMeshCache {
    fn device_key(device: &wgpu::Device) -> usize {
        std::ptr::from_ref(device).addr()
    }

    /// Returns an upload already shared for identical mesh contents on `device`.
    #[doc(hidden)]
    pub fn get(&self, device: &wgpu::Device, mesh: &Mesh) -> Option<GpuMesh> {
        let key = (Self::device_key(device), mesh_content_key(mesh));
        self.entries
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .get(&key)
            .cloned()
    }

    /// Shares a GPU upload under the device-local mesh content key.
    #[doc(hidden)]
    pub fn insert(&self, device: &wgpu::Device, mesh: &Mesh, gpu_mesh: GpuMesh) {
        let key = (Self::device_key(device), mesh_content_key(mesh));
        self.entries
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .insert(key, gpu_mesh);
    }

    /// Removes every resident upload, releasing buffers after current users drop them.
    pub fn clear(&self) {
        self.entries
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clear();
    }
}

/// Preview-only limits for GPU work admitted during one rendered frame.
///
/// Runtime worlds that do not insert this resource retain the historical eager
/// behavior. Editor previews insert a finite budget so opening a large model
/// cannot monopolize the UI render thread with one unbounded upload burst.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct GpuUploadBudget {
    /// Maximum new mesh-buffer uploads admitted this frame.
    pub max_mesh_uploads_per_frame: usize,
    /// Maximum decoded-texture uploads admitted this frame.
    pub max_texture_uploads_per_frame: usize,
}

impl Default for GpuUploadBudget {
    fn default() -> Self {
        Self {
            max_mesh_uploads_per_frame: usize::MAX,
            max_texture_uploads_per_frame: usize::MAX,
        }
    }
}

/// Deterministic per-frame progress for budgeted GPU preparation.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct GpuUploadProgress {
    /// Meshes still waiting after this frame.
    pub pending_meshes: usize,
    /// New mesh uploads completed this frame.
    pub uploaded_meshes: usize,
    /// Decoded textures deferred by the frame budget.
    pub pending_textures: usize,
    /// New decoded texture uploads completed this frame.
    pub uploaded_textures: usize,
}

impl GpuUploadProgress {
    /// Reports whether another preparation frame is required.
    pub fn has_pending(&self) -> bool {
        self.pending_meshes > 0 || self.pending_textures > 0
    }
}
